import React, { useEffect, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";
import { Link } from "@mendix/ide-ui-components/link/Link";

import { Model } from "../../../types/model/model";
import { MxCloudGenAIModelFields } from "../../../types/model/mxCloudGenAIModel";
import { handleImportKeyFromPortal, handleSelectModelKey, handleTestConnection } from "./mxCloudGenAIHandlers";

import { ConstantIcon } from "@mendix/ide-icons/ConstantIcon";
import { anthropicIconBase64 } from "../../../icons/modelIcons";
import { handleShowConstant } from "../../../utils/constantUtils";
import { clearModelDetails } from "../../../utils/modelUtils";
import { ConstantValidationErrors, validateStringConstant } from "../../../utils/validationUtils";
import { SuccessBanner, WarningBanner } from "../../components/Banner";
import ButtonWithLabel from "../../components/ButtonWithLabel";
import GroupBox from "../../components/GroupBox";
import TextInputLabeled from "../../components/TextInputLabeled";
import TextInputWithButton from "../../components/TextInputWithButton";
import { DivFlexColumn, DivFlexRow, StyledLabel } from "../../components/elements/formelements";
import { BoldText } from "../../components/elements/text";

export const KeyConstantValidationErrors = {
    ...ConstantValidationErrors,
    NotImported: "NotImported",
} as const;

export type KeyConstantValidationError = (typeof KeyConstantValidationErrors)[keyof typeof KeyConstantValidationErrors];

interface MxCloudGenAIProps {
    studioPro: StudioProApi;
    model: Model;
    setModel: React.Dispatch<React.SetStateAction<Model>>;
    updateStudioProDocument: (model: Model) => Promise<void>;
}

const emptyOnChange = () => {};

const MxCloudGenAI: React.FC<MxCloudGenAIProps> = ({ studioPro, model, setModel, updateStudioProDocument }) => {
    const [showConnectionOK, setShowConnectionOK] = useState(false);
    const [keyValidationError, setKeyValidationError] = useState<KeyConstantValidationError | undefined>();
    const providerFields = model.providerFields as MxCloudGenAIModelFields;

    const testConnection = async () => {
        setShowConnectionOK(false);
        const isSuccess: boolean = await handleTestConnection(studioPro, model, setModel, updateStudioProDocument);
        setShowConnectionOK(isSuccess);
    };

    const onBannerClose = () => {
        setShowConnectionOK(false);
    };

    const showConstant = async () => {
        if (providerFields.key) {
            handleShowConstant(studioPro, providerFields.key);
        }
    };

    const validateAndImportKey = async (model: Model) => {
        const providerFields = model.providerFields as MxCloudGenAIModelFields;
        const error = await validateStringConstant(studioPro, providerFields.key);

        setKeyValidationError(error);
        setShowConnectionOK(false);

        if (!error) {
            handleImportKeyFromPortal(studioPro, model, setModel, setKeyValidationError, updateStudioProDocument);
        } else {
            const clearedModel = clearModelDetails(model);
            setModel(clearedModel);
            updateStudioProDocument(clearedModel);
        }
    };

    const selectKey = async () => {
        const updatedModel = await handleSelectModelKey(studioPro, model);

        if (updatedModel) {
            setModel(updatedModel);
            updateStudioProDocument(updatedModel);
            await validateAndImportKey(updatedModel);
        }
    };

    useEffect(() => {
        if (showConnectionOK) {
            const timer = setTimeout(() => {
                setShowConnectionOK(false);
            }, 5000);
            return () => clearTimeout(timer);
        }
    }, [showConnectionOK]);

    useEffect(() => {
        const validateKey = async () => {
            const error = await validateStringConstant(studioPro, providerFields.key);
            setKeyValidationError(error);
        };
        validateKey();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const getErrorMessage = (error: KeyConstantValidationError | undefined): string | true => {
        if (error === KeyConstantValidationErrors.Required) {
            return "Model key is required";
        } else if (error === KeyConstantValidationErrors.NotFound) {
            return "Selected constant not found. It might have been deleted or renamed. Please update the constant selection.";
        } else if (error === KeyConstantValidationErrors.InvalidType) {
            return "Selected constant must be of type string.";
        } else if (error === KeyConstantValidationErrors.Excluded) {
            return "Selected constant is excluded from the project and cannot be used.";
        }

        return true;
    };

    const showConstantWarning =
        keyValidationError === KeyConstantValidationErrors.EmptyValue ||
        keyValidationError === KeyConstantValidationErrors.PrivateValue ||
        keyValidationError === KeyConstantValidationErrors.NotImported;

    return (
        <GroupBox label="Resource">
            <TextInputWithButton
                label="Model key"
                ariaLabel="Model key"
                value={providerFields.key?.qualifiedName ?? ""}
                icon={providerFields.key ? <ConstantIcon /> : undefined}
                buttonCaption="Select..."
                onClick={selectKey}
                onClickSecondary={providerFields.key ? showConstant : undefined}
                validate={() => getErrorMessage(keyValidationError)}
                buttonCaptionSecondary={providerFields.key ? "Show" : undefined}
            />
            {!providerFields.key && (
                <DivFlexRow>
                    <DivFlexColumn>
                        <StyledLabel></StyledLabel>
                    </DivFlexColumn>
                    <DivFlexColumn fullWidth>
                        <Link href="https://genai.home.mendix.com/p/resources" target="_blank">
                            Create a key in the portal
                        </Link>
                    </DivFlexColumn>
                </DivFlexRow>
            )}
            {showConstantWarning && (
                <WarningBanner>
                    <BoldText>Invalid constant value</BoldText>
                    <div>In order to test your Model locally please set a valid value for the key constant.</div>
                </WarningBanner>
            )}
            {providerFields.keyId && (
                <>
                    <TextInputLabeled
                        label="Resource"
                        ariaLabel="Resource name"
                        value={providerFields.resourceName}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Key"
                        ariaLabel="Key name"
                        value={providerFields.keyName}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Model"
                        ariaLabel="Model name"
                        value={model.displayName}
                        icon={
                            model.displayName && model.displayName.toLocaleLowerCase().includes("anthropic")
                                ? anthropicIconBase64
                                : undefined
                        }
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Model ID"
                        ariaLabel="Model ID"
                        value={model.name}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Environment"
                        ariaLabel="Environment"
                        value={providerFields.environment}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <DivFlexRow>
                        <DivFlexColumn>
                            <StyledLabel></StyledLabel>
                        </DivFlexColumn>
                        <DivFlexColumn fullWidth>
                            <Link href={providerFields.deepLinkURL} target="_blank">
                                View resource in the portal
                            </Link>
                        </DivFlexColumn>
                    </DivFlexRow>
                    <ButtonWithLabel label="Connection" buttonCaption="Test" onPress={testConnection} />
                    {showConnectionOK && <SuccessBanner onClose={onBannerClose}>Connection successful.</SuccessBanner>}
                </>
            )}
        </GroupBox>
    );
};

export default MxCloudGenAI;
